"""Interview question bank: short conceptual questions with model answers, basic → advanced."""
from sd_util2 import Q

QA = [
# ---------- Basic ----------
Q("Basic", "Fundamentals", "What is the difference between horizontal and vertical scaling?",
  "Vertical = bigger machine (more CPU/RAM); simple but has a ceiling and is a single point of failure. Horizontal = more machines behind a load balancer; nearly unlimited and fault tolerant, but needs stateless services and data partitioning."),
Q("Basic", "Fundamentals", "What is latency vs throughput?",
  "Latency is the time for one request (e.g. 80 ms, measured as p50/p99). Throughput is how many requests are completed per second. Adding servers raises throughput; it doesn't by itself lower latency."),
Q("Basic", "Fundamentals", "What does 99.99% availability mean in downtime?",
  "About 52.6 minutes per year (≈4.4 minutes per month). Each extra nine is 10x less downtime."),
Q("Basic", "Fundamentals", "What is a single point of failure and how do you remove it?",
  "A component whose failure stops the whole system (one DB, one load balancer). Remove it with redundancy: replicas, multiple instances across availability zones, automatic failover, and health checks."),
Q("Basic", "Fundamentals", "Why should application servers be stateless?",
  "So any server can handle any request: you can add/remove servers freely, the load balancer needs no stickiness, and a crash loses no user state. Keep sessions in Redis/DB or in tokens."),
Q("Basic", "Networking", "What happens when you type google.com in the browser?",
  "DNS resolves the name to an IP → TCP handshake → TLS handshake → HTTP GET → CDN/load balancer → app server (cache/DB) → response → browser parses HTML, fetches CSS/JS/images, renders."),
Q("Basic", "Networking", "TCP vs UDP — when would you use UDP?",
  "TCP is reliable and ordered (web, DBs, payments). UDP has no delivery or order guarantees but lower latency; use it when late data is useless: live video/voice, games, DNS, QUIC."),
Q("Basic", "Networking", "What is DNS and how can it help with load balancing?",
  "DNS maps names to IP addresses through a cached hierarchy (resolver → root → TLD → authoritative). It can return multiple IPs (round robin) or region-specific IPs (GeoDNS/latency routing) and fail over using health checks."),
Q("Basic", "Networking", "What are idempotent HTTP methods and why does it matter?",
  "GET, PUT, DELETE (and HEAD/OPTIONS) give the same result if repeated; POST usually doesn't. Idempotency makes retries after timeouts safe. For POST, add an Idempotency-Key."),
Q("Basic", "Networking", "301 vs 302 redirect?",
  "301 = permanent; browsers and proxies cache it (less load, but later clicks may never reach your server). 302/307 = temporary; every visit hits your server (good for analytics, e.g. URL shorteners)."),
Q("Basic", "APIs", "REST vs GraphQL vs gRPC?",
  "REST: resource URLs + JSON, simple, cacheable — public APIs. GraphQL: client asks for exactly the fields it needs in one request — many clients with varied needs. gRPC: binary Protobuf over HTTP/2, typed and fast, streaming — internal service-to-service calls."),
Q("Basic", "APIs", "Offset vs cursor pagination?",
  "Offset (`LIMIT 20 OFFSET 1000`) is simple but slow for deep pages and unstable when rows are inserted. Cursor/keyset (`WHERE id < last_seen ORDER BY id DESC LIMIT 20`) is fast and stable; used for feeds."),
Q("Basic", "Load balancing", "What does a load balancer do?",
  "Spreads requests across healthy servers, removes failed ones via health checks, and can terminate TLS, route by path (L7), and enable zero-downtime deploys."),
Q("Basic", "Load balancing", "L4 vs L7 load balancer?",
  "L4 routes by IP/port without reading the request — very fast. L7 reads HTTP (path, headers, cookies) — can route /api vs /images, terminate TLS, do rate limiting; slightly more overhead."),
Q("Basic", "Caching", "What is caching and where can you cache?",
  "Keeping copies of frequently read data in fast storage. Layers: browser, CDN, reverse proxy, in-process app cache, distributed cache (Redis), DB buffer cache."),
Q("Basic", "Caching", "What is a CDN?",
  "A globally distributed set of edge servers that cache static (and some dynamic) content near users, cutting latency and origin load. Pull CDNs fetch on first miss; push CDNs are pre-loaded."),
Q("Basic", "Caching", "Explain LRU eviction and how to implement it in O(1).",
  "Evict the least recently used entry. Use a HashMap (key → node) plus a doubly linked list ordered by recency: move to head on access, remove from tail on eviction."),
Q("Basic", "Databases", "SQL vs NoSQL — how do you choose?",
  "SQL for relational data needing joins and ACID transactions (orders, payments, inventory). NoSQL for huge scale with simple key-based access, flexible schemas, or very high write volume (chat, events, catalogues). Choose by access pattern and consistency needs."),
Q("Basic", "Databases", "What is ACID?",
  "Atomicity (all or nothing), Consistency (constraints hold), Isolation (concurrent transactions don't interfere), Durability (committed data survives crashes)."),
Q("Basic", "Databases", "What is a database index and what does it cost?",
  "A sorted structure (usually a B+tree) that finds rows in O(log n) instead of scanning. Costs: extra storage and slower writes, since every index must be updated."),
Q("Basic", "Databases", "What is replication and why use it?",
  "Keeping copies of data on several nodes: higher availability (failover), durability, and read scaling (read replicas)."),
Q("Basic", "Databases", "What is sharding?",
  "Splitting data across multiple databases by a shard key (e.g. user_id hash) so storage and write load scale horizontally."),
Q("Basic", "Async", "Why use a message queue?",
  "To decouple services, absorb traffic spikes, process slow work asynchronously (emails, video encoding), retry failures and scale consumers independently."),
Q("Basic", "Async", "Queue vs pub/sub?",
  "Queue: each message is processed by one consumer (work distribution). Pub/sub: each message is delivered to every subscriber group (fan-out of events)."),
Q("Basic", "Storage", "Where should you store images and videos?",
  "In object storage (S3/GCS) served through a CDN, with only metadata (URL, size, owner) in the database. Upload directly with pre-signed URLs."),
Q("Basic", "Security", "Authentication vs authorization?",
  "Authentication verifies who you are (login, tokens). Authorization decides what you may do (roles/permissions), checked on every request on the server."),
Q("Basic", "Security", "How should passwords be stored?",
  "Never in plain text or with fast hashes. Use a slow salted hash: bcrypt, scrypt or Argon2. Add rate limiting and MFA."),
Q("Basic", "Estimation", "1 million requests per day is roughly how many per second?",
  "About 12 per second (1M ÷ 86,400). Peak is typically 2–3x average."),
Q("Basic", "LLD", "Explain SOLID in one line each.",
  "S: one reason to change. O: extend without modifying. L: subclasses must be usable as their parent. I: small focused interfaces. D: depend on abstractions and inject them."),
Q("Basic", "LLD", "Composition vs inheritance?",
  "Inheritance = is-a, fixed at compile time, can create rigid hierarchies. Composition = has-a, swap behaviour at runtime (Strategy). Prefer composition unless there's a true is-a relationship."),

# ---------- Intermediate ----------
Q("Intermediate", "Caching", "Compare cache-aside, write-through and write-back.",
  "Cache-aside: app loads on miss and deletes on write — simple, default. Write-through: write to cache and DB together — fresh cache, slower writes. Write-back: write to cache, flush to DB later — fastest writes, risk of loss if cache dies."),
Q("Intermediate", "Caching", "Why delete the cache key on update instead of updating it?",
  "Two concurrent writers can update the cache in a different order than the DB, leaving stale data permanently. Deleting forces the next read to load the current DB value; TTLs cover any remaining race."),
Q("Intermediate", "Caching", "What is a cache stampede and how do you prevent it?",
  "Many requests miss a hot key at once (after expiry) and all hit the DB. Prevent with single-flight locking (one rebuilds, others wait/serve stale), early probabilistic refresh, and TTL jitter."),
Q("Intermediate", "Caching", "How do you handle a hot key in Redis?",
  "Local in-process cache for that key, replicate it under several keys (key#1..#N) and read a random copy, or put it on the CDN. Detect hot keys with metrics/sampling."),
Q("Intermediate", "Caching", "Redis vs Memcached?",
  "Memcached: simple multithreaded string cache. Redis: rich data structures (sorted sets, hashes, streams, HyperLogLog), persistence, replication, clustering, Lua scripts, pub/sub — used for caching plus counters, leaderboards, locks, rate limiting."),
Q("Intermediate", "Load balancing", "Which load-balancing algorithm would you pick for WebSocket servers?",
  "Least connections (connections are long-lived and uneven), with health checks. Round robin would pile connections onto servers unevenly over time."),
Q("Intermediate", "Load balancing", "Why avoid sticky sessions?",
  "They unbalance load, make failover lose user state, and complicate scaling. Prefer stateless servers with a shared session store."),
Q("Intermediate", "Databases", "Explain the isolation levels and anomalies.",
  "Read uncommitted (dirty reads possible) → read committed (no dirty reads; non-repeatable reads possible) → repeatable read (no non-repeatable reads; phantoms possible) → serializable (as if one at a time). Higher levels prevent more anomalies but reduce concurrency."),
Q("Intermediate", "Databases", "Optimistic vs pessimistic locking?",
  "Pessimistic: lock rows before updating (`SELECT ... FOR UPDATE`) — good under high contention. Optimistic: read a version, update with `WHERE version = v`, retry on conflict — better when conflicts are rare."),
Q("Intermediate", "Databases", "How do you prevent two users booking the same seat?",
  "Make the claim atomic: `UPDATE seats SET status='HELD', user=? WHERE id=? AND status='AVAILABLE'` and check rows affected = 1; or a unique constraint on (show, seat) in bookings; or optimistic versions. Add hold expiry for unpaid seats."),
Q("Intermediate", "Databases", "What is replication lag and how do you deal with read-your-own-writes?",
  "Async followers trail the leader by ms–seconds. After a user writes, read their own data from the leader for a short window (or track the write's log position and read from a replica that has caught up)."),
Q("Intermediate", "Databases", "Synchronous vs asynchronous replication?",
  "Sync waits for replicas before acknowledging — no data loss on failover but higher latency and blocked writes if a replica is slow. Async acknowledges immediately — fast, but recent writes can be lost on failover. Semi-sync waits for one replica."),
Q("Intermediate", "Databases", "How do you choose a shard key?",
  "High cardinality, even distribution, matches the dominant query (keep a user's data together), avoids hot spots (not timestamps or country). Example: user_id for social apps, conversation_id for chat."),
Q("Intermediate", "Databases", "What problems does sharding introduce?",
  "Cross-shard joins/queries (scatter-gather), cross-shard transactions, hot shards, rebalancing/resharding, global unique IDs, and operational complexity."),
Q("Intermediate", "Databases", "Why does consistent hashing help with resharding?",
  "With hash % N, changing N remaps almost all keys. On a hash ring, adding a node only takes keys from its neighbour (~1/N of data). Virtual nodes even out the distribution."),
Q("Intermediate", "Databases", "B-tree vs LSM tree?",
  "B-tree updates pages in place — fast reads, used by most SQL DBs. LSM tree appends to a memtable and sorted files, compacting later — very fast writes, used by Cassandra/RocksDB; reads use Bloom filters to skip files."),
Q("Intermediate", "Databases", "When would you denormalize?",
  "For read-heavy screens where joins are too slow or span shards: store author name in posts, precomputed counters, per-screen read models. Accept extra write work and keep copies in sync via events."),
Q("Intermediate", "Databases", "What is the N+1 query problem?",
  "Fetching a list with one query and then one more query per item (often via ORM lazy loading). Fix with JOIN FETCH, batch `IN (...)` queries, or DataLoader."),
Q("Intermediate", "Async", "What is a dead-letter queue?",
  "A queue where messages go after failing N processing attempts, so they don't block the main queue. Alert on it, inspect, fix and replay."),
Q("Intermediate", "Async", "How does Kafka guarantee ordering and how do consumer groups work?",
  "Ordering is per partition; messages with the same key go to the same partition. In a consumer group each partition is consumed by exactly one consumer, so parallelism ≤ partition count."),
Q("Intermediate", "Async", "At-least-once vs exactly-once?",
  "At-least-once: ack after processing, so crashes can cause duplicates. Exactly-once end-to-end is achieved in practice as at-least-once delivery + idempotent processing (dedupe by message ID, upserts) or transactional systems like Kafka transactions."),
Q("Intermediate", "Async", "Kafka vs RabbitMQ?",
  "Kafka: durable replayable log, very high throughput, many consumer groups, per-partition order — event streaming. RabbitMQ/SQS: message deleted after ack, flexible routing, per-message acks/priorities — task queues."),
Q("Intermediate", "Distributed", "Explain the CAP theorem.",
  "During a network partition a distributed store must choose consistency (refuse/stale-free) or availability (answer with possibly stale data). Partitions are unavoidable, so the choice is CP vs AP, often per feature."),
Q("Intermediate", "Distributed", "Strong vs eventual consistency — give examples.",
  "Strong: after a write, all reads see it (bank balance, inventory, usernames). Eventual: replicas converge over time (likes, view counts, feeds, DNS)."),
Q("Intermediate", "Distributed", "How do you generate unique IDs across many servers?",
  "UUIDs (no coordination, not sortable), Snowflake (timestamp + machine ID + sequence; 64-bit, time-sortable), ticket servers handing out ranges, or DB sequences with offsets."),
Q("Intermediate", "Distributed", "What is a Bloom filter and where is it used?",
  "A bit array + k hashes answering 'definitely not' or 'probably yes' for set membership in tiny memory. Used by LSM databases to skip files, crawlers for seen URLs, and to block cache penetration."),
Q("Intermediate", "Architecture", "Monolith vs microservices — when to choose which?",
  "Start with a (modular) monolith for small teams and new products. Move to microservices when independent deployment/scaling across many teams outweighs the cost of network calls, distributed data and operations."),
Q("Intermediate", "Architecture", "What is an API gateway responsible for?",
  "Single entry point: routing, authentication, rate limiting, TLS termination, request aggregation, logging/metrics, canary routing. Keep business logic out of it."),
Q("Intermediate", "Architecture", "What is a circuit breaker?",
  "A wrapper that stops calling a failing dependency after a failure threshold (open), fails fast for a cool-down, then lets trial calls through (half-open) before closing again. Prevents cascading failures and gives the dependency time to recover."),
Q("Intermediate", "Architecture", "Why add jitter to retries?",
  "Without jitter, many clients retry at the same moments and hammer the recovering service in synchronized waves. Random jitter spreads retries out."),
Q("Intermediate", "Architecture", "What is the bulkhead pattern?",
  "Isolating resources (thread pools, connection pools) per dependency so one slow dependency can't exhaust resources needed by others."),
Q("Intermediate", "Architecture", "Explain blue-green vs canary deployment.",
  "Blue-green: a full new environment, switch all traffic at once, instant rollback by switching back. Canary: shift a small percentage of traffic to the new version, watch metrics, increase gradually."),
Q("Intermediate", "Architecture", "How do services find each other in Kubernetes?",
  "Through Services: a stable DNS name and virtual IP that load-balances across healthy pods (kube-proxy/iptables or a service mesh)."),
Q("Intermediate", "Reliability", "RPO vs RTO?",
  "RPO = maximum acceptable data loss (time since last recoverable copy). RTO = maximum acceptable downtime to restore service. They drive backup frequency and standby strategy."),
Q("Intermediate", "Reliability", "What are metrics, logs and traces used for?",
  "Metrics: cheap aggregated numbers for dashboards and alerts. Logs: detailed records of individual events for debugging. Traces: follow one request across services to find where time or errors occur."),
Q("Intermediate", "Reliability", "What should you alert on?",
  "User-facing symptoms tied to SLOs (error rate, latency, availability, SLO burn rate), not every internal metric. Every alert must be actionable with a runbook."),
Q("Intermediate", "Security", "Sessions vs JWT?",
  "Sessions: random ID in a cookie, state on the server — easy revocation, needs a store lookup. JWT: signed self-contained token — stateless verification across services, but hard to revoke, so use short expiry plus refresh tokens."),
Q("Intermediate", "Security", "How does OAuth 2.0 authorization code flow work?",
  "App redirects user to the auth server → user logs in/consents → auth server redirects back with a code → app exchanges code (+PKCE verifier) for access/refresh tokens on a back channel → app calls the API with the access token."),
Q("Intermediate", "Security", "How do you protect against DDoS?",
  "Absorb at the edge with CDN/Anycast and DDoS services (Cloudflare, AWS Shield), WAF rules, rate limiting per IP/key, autoscaling, and dropping bad traffic early; keep origins hidden."),
Q("Intermediate", "Patterns", "Fan-out on write vs fan-out on read?",
  "Write: push each post into followers' feeds at post time — fast reads, expensive for celebrities. Read: assemble the feed at read time — cheap writes, slow reads. Use a hybrid: push for normal users, pull for celebrities."),
Q("Intermediate", "Patterns", "How do you count likes on a viral post without overloading one row?",
  "Shard the counter (N sub-counters summed on read), batch increments in Redis and flush periodically, or aggregate like events in a stream job; show approximate counts."),
Q("Intermediate", "Patterns", "How do you find nearby restaurants efficiently?",
  "Index locations with geohash (search the cell + 8 neighbours), a quadtree, or S2/H3 cells; filter by exact distance, then rank. Cache popular areas."),
Q("Intermediate", "Patterns", "How do WebSocket chat servers deliver a message to a user on another server?",
  "Keep a registry (Redis) of user → connected server; the sender's server publishes the message to the recipient's server via pub/sub or direct RPC, which pushes it over the socket. If offline, store it and send a push notification."),
Q("Intermediate", "Estimation", "Estimate storage for 500M users posting one 2 MB photo per day for a year.",
  "500M × 2 MB = 1 PB/day → ~365 PB/year, ×3 for replication or ×1.5 with erasure coding, plus thumbnails. Clearly object storage with tiering."),
Q("Intermediate", "LLD", "Which design patterns would you use for a parking lot?",
  "Strategy for fee calculation and spot allocation, Factory for vehicles/spots, Observer for display boards, Singleton only if required (prefer dependency injection), enums for types."),
Q("Intermediate", "LLD", "How would you make an LRU cache thread-safe?",
  "Guard get/put with a lock (ReentrantLock or synchronized) since both mutate the list; for high concurrency use striped/sharded caches or a library like Caffeine with concurrent buffers."),
Q("Intermediate", "LLD", "When is the State pattern better than if/else?",
  "When behaviour depends on many states and transitions (vending machine, order lifecycle, elevator). Each state is a class handling its allowed actions, so adding a state doesn't touch a giant switch."),

# ---------- Advanced ----------
Q("Advanced", "Distributed", "What is PACELC and why is it more useful than CAP?",
  "If Partition: choose Availability or Consistency; Else: choose Latency or Consistency. It captures that even without failures, stronger consistency costs latency (waiting for replicas)."),
Q("Advanced", "Distributed", "Explain quorum reads and writes (R + W > N).",
  "With N replicas, writes wait for W acks and reads ask R replicas. If R + W > N, every read set overlaps the latest write set, so the newest version (by version number) is seen. Tune for read/write latency vs consistency."),
Q("Advanced", "Distributed", "How does Raft elect a leader and replicate logs?",
  "Followers with no heartbeat before a random timeout become candidates, increment the term and request votes; a majority makes a leader. The leader appends client commands, replicates to followers, and commits an entry once a majority stores it. Votes only go to candidates with up-to-date logs."),
Q("Advanced", "Distributed", "Why do consensus clusters have odd sizes like 3 or 5?",
  "A majority is needed. 3 nodes tolerate 1 failure, 5 tolerate 2; 4 nodes still tolerate only 1, so the extra node adds cost without more fault tolerance."),
Q("Advanced", "Distributed", "What is split brain and how is it prevented?",
  "Two nodes both act as leader (e.g. after a partition). Prevent with majority quorums, leases that expire, STONITH/fencing, and fencing tokens checked by storage."),
Q("Advanced", "Distributed", "Why is a Redis lock with expiry not enough for correctness?",
  "A holder may pause (GC, network) past expiry while another client acquires the lock; both then write. Use fencing tokens (monotonic numbers checked by the resource) and a consensus-backed lock service for correctness-critical cases."),
Q("Advanced", "Distributed", "Lamport clocks vs vector clocks?",
  "Lamport clocks give a total order consistent with causality but can't tell whether two events are concurrent. Vector clocks track a counter per node and can detect concurrency (conflicts), at the cost of size growing with node count."),
Q("Advanced", "Distributed", "How does Spanner achieve external consistency globally?",
  "TrueTime provides bounded clock uncertainty using GPS and atomic clocks; Spanner assigns commit timestamps and waits out the uncertainty (commit wait) before making writes visible, combined with Paxos-replicated groups and 2PC across groups."),
Q("Advanced", "Distributed", "What are CRDTs and where would you use them?",
  "Data types whose concurrent updates merge deterministically without coordination (G-counter, OR-set, sequence CRDTs). Use for multi-region active-active counters/sets, offline-first apps and collaborative editing."),
Q("Advanced", "Distributed", "How do Dynamo-style systems repair inconsistent replicas?",
  "Read repair during reads, hinted handoff for temporarily down nodes, and periodic anti-entropy using Merkle trees to find and sync differing key ranges efficiently."),
Q("Advanced", "Distributed", "What is a gossip protocol?",
  "Each node periodically exchanges state with a few random peers, spreading information to all nodes in O(log N) rounds without a central coordinator; used for membership and failure detection (Cassandra, Consul)."),
Q("Advanced", "Transactions", "2PC vs Saga?",
  "2PC: coordinator gets all participants to prepare then commit — atomic but blocking and slow, poor across microservices. Saga: sequence of local transactions with compensating actions on failure — available and scalable, eventually consistent."),
Q("Advanced", "Transactions", "What is the transactional outbox pattern?",
  "Write the business change and an outbox event row in the same DB transaction; a relay (poller or CDC) publishes outbox rows to the message broker. Solves the dual-write problem with at-least-once delivery."),
Q("Advanced", "Transactions", "How would you design idempotency for a payment API?",
  "Client sends an Idempotency-Key; server inserts (key, request hash, status) with a unique constraint before processing; duplicates return the stored response; pass our payment ID as the idempotency key to the PSP; use conditional state transitions; reconcile with PSP reports."),
Q("Advanced", "Data", "Event sourcing — benefits and drawbacks?",
  "Store every change as an immutable event: full audit history, temporal queries, rebuildable projections. Drawbacks: replay cost (needs snapshots), schema evolution of old events, complexity, eventual consistency of read models."),
Q("Advanced", "Data", "What is CDC and why prefer it over dual writes?",
  "Change Data Capture streams committed changes from the DB log (binlog/WAL) to consumers. It avoids dual-write inconsistency (DB updated but event lost) and keeps caches, search indexes and warehouses in sync."),
Q("Advanced", "Data", "How would you migrate a large table to a new schema with zero downtime?",
  "Expand–contract: add new columns/table, dual-write (or CDC backfill), backfill historical data in batches, verify, switch reads behind a flag, stop old writes, then drop old columns."),
Q("Advanced", "Data", "How do you handle a hot partition in DynamoDB/Cassandra?",
  "Add a random or time-based suffix to spread the key (write sharding) and aggregate on read; cache hot reads; redesign the partition key for higher cardinality."),
Q("Advanced", "Data", "How would you implement global secondary indexes in a sharded DB?",
  "Partition the index by the indexed value (global index) so lookups hit one shard; update it asynchronously (eventually consistent) or with distributed transactions. Local indexes are simpler but require scatter-gather queries."),
Q("Advanced", "Streaming", "Event time vs processing time; what is a watermark?",
  "Event time is when it happened; processing time is when the system sees it. A watermark asserts 'events up to time T have probably arrived', letting windows close while allowing configurable lateness for stragglers."),
Q("Advanced", "Streaming", "How would you compute top-K trending hashtags in real time?",
  "Partition events by hashtag, count in sliding windows (per-minute buckets) with exact maps or Count-Min Sketch, keep a heap of local top-K per worker, and merge into a global top-K every minute; filter spam; batch job for exact daily lists."),
Q("Advanced", "Streaming", "Lambda vs Kappa architecture?",
  "Lambda runs a batch layer (accurate) and a speed layer (fast) and merges results — two code paths. Kappa uses only stream processing and reprocesses by replaying the log — one code path."),
Q("Advanced", "Scale", "How would you design for multi-region active-active writes?",
  "Partition users to a home region where possible; for shared data use conflict-free designs (CRDTs), last-write-wins with care, or a globally consistent DB (Spanner/CockroachDB) for critical data; route with GeoDNS; replicate asynchronously; plan for region evacuation."),
Q("Advanced", "Scale", "What is tail latency amplification and how do you reduce it?",
  "When a request fans out to many services/shards, its latency is the slowest one, so p99 dominates. Reduce with hedged/backup requests, replicas, timeouts, smaller fan-out, caching and removing GC pauses."),
Q("Advanced", "Scale", "How do you handle the celebrity problem in feeds?",
  "Don't fan out celebrity posts on write; merge them at read time with the user's precomputed feed; cache celebrity posts aggressively."),
Q("Advanced", "Scale", "How would you survive a flash sale with 100x traffic?",
  "Pre-scale and load-test, CDN for static pages, virtual waiting room to admit users at a sustainable rate, inventory in Redis with atomic decrements and async persistence, queue order intake, rate limit and bot detection, isolate the sale from the rest of the site, fail fast with 'sold out'."),
Q("Advanced", "Reliability", "How do you prevent retry storms and cascading failures?",
  "Timeouts with deadlines, capped retries with exponential backoff + jitter, retry budgets, circuit breakers, bulkheads, load shedding of low-priority traffic, and backpressure."),
Q("Advanced", "Reliability", "What is an error budget?",
  "100% minus the SLO (e.g. 0.1% for 99.9%). While budget remains, teams can ship risky changes; when it's exhausted, they prioritise reliability work."),
Q("Advanced", "Storage", "Replication vs erasure coding for object storage?",
  "3x replication: simple, fast reads/repairs, 200% overhead. Erasure coding (e.g. 6 data + 3 parity): ~50% overhead with similar durability, but more CPU and slower repairs; often used for colder data."),
Q("Advanced", "Search", "How does a search engine serve a query across hundreds of index shards fast?",
  "Document-partitioned shards each return their top results in parallel; an aggregator merges them; replicas absorb load; hedged requests cut tail latency; popular queries are cached; heavy ML ranking runs only on the merged top few hundred."),
Q("Advanced", "Security", "What is zero trust and mTLS?",
  "Zero trust: no implicit trust from network location; every request is authenticated and authorised. mTLS: both client and server present certificates, giving encrypted, mutually authenticated service-to-service calls (often via a service mesh)."),
Q("Advanced", "GenAI", "How would you design a RAG chatbot over company documents?",
  "Ingest: chunk documents, embed, store in a vector DB with metadata and ACLs. Query: embed the question, ANN search (with permission filters), re-rank, build a prompt with citations, stream the LLM answer. Add caching, rate limits, guardrails, evaluation and feedback loops."),
Q("Advanced", "LLD", "How do you avoid deadlocks in a multithreaded design?",
  "Acquire locks in a consistent global order, hold locks briefly, use tryLock with timeouts, prefer lock-free structures (atomics, ConcurrentHashMap) or single-threaded ownership, and avoid calling external code while holding locks."),
Q("Advanced", "LLD", "How would you make a booking system safe under concurrency without a global lock?",
  "Lock per resource (per show or per seat), use atomic putIfAbsent on a ConcurrentHashMap of seat → holder, or optimistic versions; in distributed systems use conditional DB updates or unique constraints."),
]
